/* ===== ring + crowd scene above the live show log ===== */
const CROWD_SRC='data:image/webp;base64,';
const RING_SRC='data:image/webp;base64,';
(function(){const _vs=vShow;vShow=function(){const h=_vs.apply(this,arguments);
 try{if(typeof RUN!=='undefined'&&RUN){const sc='<div class="stage" aria-hidden="true"><img class="stg-ring" src="'+RING_SRC+'" alt=""><img class="stg-crowd" src="'+CROWD_SRC+'" alt=""></div>';const k='<div class="card"><div id="live"';return h.indexOf(k)>=0?h.replace(k,sc+k):h+sc}}catch(e){}return h};
 try{if(typeof document!=='undefined'&&!document.getElementById('crowdcss')){const s=document.createElement('style');s.id='crowdcss';s.textContent='.stage{position:relative;margin:4px 0 14px;pointer-events:none;user-select:none}.stg-ring{display:block;width:min(430px,48%);margin:0 auto;position:relative;z-index:1;filter:drop-shadow(0 8px 14px rgba(0,0,0,.45))}.stg-crowd{display:block;width:100%;margin-top:-17%;position:relative;z-index:2;transform-origin:50% 100%;animation:crowdbob 1.7s ease-in-out infinite}@keyframes crowdbob{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}@media (prefers-reduced-motion:reduce){.stg-crowd{animation:none}}';document.head.appendChild(s)}}catch(e){}
})();
